INSERT INTO leads (id, data, updated_at, version) VALUES ('L-5592', '{"id":"L-5592","key":"L-5592","name":"炒股盘的APP开发","customer":"","contact":"","phone":"","wechat":"","source":"baidu","keyword":"1154983","status":"未联系","clueType":"trash","level":"","customerLevel":"A","tags":["一、三端功能rn用户端：手机号/一键登录、实名认证；首页轮播+秒杀+拼团+满减+新人福利；商品浏览搜索、购物车、收藏；下单支付、物流查询、售后退款；优惠券、积分签到抵扣、抽奖；一级分销（推广码/海报/直推佣金/分享）；余额提现、佣金明细；资讯推送、客服私聊、个人中心。rn商家端：店铺装修及产品上下架；接单发货、售后处理；自主发券、设活动价、设推广佣金；销售数据/每日报表；商户提现对账；会员管理及标签。rn后台：用户/商家/商品审核管理；全局营销规则及佣金比例配置；全平台订单、分账、提现审核；数据统计报表；公告推送、风控管控。rn二、营销活动：新人红包/首单立减→秒杀/拼团/满减→签到积分/会员折扣→一级分销/好友助力→抽奖/短视频带货。rn三、技术架构：安卓+iOS双端APP，H5适配微信；Java/PHP后端+MySQL+Redis；对接短信、微信/支付宝支付、地图、推送、实名认证接口；自动分账+佣金结算+提现打款+完整流水。rn四、开发流程：定模式→原型UI→后端接口→前端开发→第三方调试→全量测试→双端上架→备案合规→维护更新。rn五、合规：一级分销、无多层级计酬、无静态收益、资金走官方支付、"],"entity":"","owner":"","optimizer":"","assistant":"","creator":"李翔龙","createTime":"2026-05-29 14:20","updateTime":"2026-05-29 14:20","lastFollowTime":"2026-06-04 09:31","lastFollowContent":"电话打不通","nextFollowTime":"2026-06-05 10:00","followCount":0,"daysHeld":0,"trashCount":1,"transformStatus":false,"isOverdue":false,"remark":"","customerBudget":"","customerCost":"","presalesGroupName":"","prototypeLink":"","witkeyId":"","witkeyTaskNo":"","customerNote":"","initialRequirement":""}', '2026-05-29 14:20', 0) ON CONFLICT (id) DO NOTHING;
