INSERT INTO leads (id, data, updated_at, version) VALUES ('L-5759', '{"id":"L-5759","key":"L-5759","name":"毛竹识别小程序开发","customer":"","contact":"","phone":"","wechat":"","source":"baidu","keyword":"1156364","status":"未联系","clueType":"public","level":"","customerLevel":"A","tags":["核心功能需求n1. 首页（相机页面）n 打开小程序直接进入相机预览界面，无需登录、无需注册。n2. 界面底部两个按钮：n• 拍竹兜照片n• 从相册选择n• 底部提示语：拍摄建议n• 拍摄毛竹根部及一米区域内地面特征，n底部提示• 确保光线充足画面清晰n• 仅限毛竹识别，其他品种不适宜n3. 视频识别流程n1. 用户点击「拍摄」n2. 后台自动进行分析识别(固定规则）：n• 识别竹兜弯曲方向及弯曲度n• 识别竹兜深度n• 识别地面坡度n3. 上传后台，算法根据毛竹形态，对结果综合判断，推理竹鞭大致位置走向。n1～3秒内返回识别结果图。(首次拍照识别免费，第二次后一元一次，付款后显示识别结果）n4. 结果图展示页n展示：竹兜截图 +红色箭头标注竹鞭延伸方向+虚线标示大致范围。n 免责提示：n• 本结果为AI+经验算法辅助判断，不代表100%准确，仅供挖笋参考。n5. 非功能要求n1. 界面整体风格极简，无广告、无弹窗、无跳转外链。绿色/竹林主题色调。n2. 字体清晰，按钮大，方便户外单手操作。3. 无多余装饰元素，突出相机与识别结果。"],"entity":"","owner":"","optimizer":"","assistant":"","creator":"吴丹丹","createTime":"2026-06-18 11:17","updateTime":"2026-06-18 11:17","lastFollowTime":"2026-07-29 11:31","lastFollowContent":"加微信一直没通过","nextFollowTime":"2026-07-30 10:00","followCount":0,"daysHeld":0,"trashCount":0,"transformStatus":false,"isOverdue":false,"remark":"","customerBudget":"","customerCost":"","presalesGroupName":"","prototypeLink":"","witkeyId":"","witkeyTaskNo":"","customerNote":"","initialRequirement":"1000"}', '2026-06-18 11:17', 0) ON CONFLICT (id) DO NOTHING;
