INSERT INTO leads (id, data, updated_at, version) VALUES ('L-5783', '{"id":"L-5783","key":"L-5783","name":"基于heliboard-v3.9开源代码开发中文输入法","customer":"","contact":"","phone":"","wechat":"","source":"baidu","keyword":"","status":"未联系","clueType":"public","level":"","customerLevel":"A","tags":["一、前期环境准备（10分钟即可完成）n你已经有heliboard-v3.9源码，只需要配置标准开发环境即可：n用Android Studio Hedgehog/2023+打开项目，配置NDK 25.x+（heliboard少量原生逻辑适配这个版本兼容性最好），把项目的compileSdk/targetSdk调整为34，minSdk设为21（覆盖绝大多数安卓/鸿蒙兼容设备）。n添加依赖：在app模块的build.gradle添加OkHttp+Gson依赖，用于调用多文API。n二、核心对接改造（半天可完成调通）n1. 基础权限配置n打开AndroidManifest.xml，添加网络权限：n输入法的核心服务声明保持heliboard原有配置即可，安卓/鸿蒙都会自动识别。n2. 替换输入引擎逻辑对接多文APInheliboard原有核心输入逻辑在com.heliboard.engine包下，只需要修改两处：n拼音输入场景：把用户输入的编码串，按多文API要求封装参数，异步调用API，将返回的候选词数组直接替换原有heliboard的候选列表即可。"],"entity":"","owner":"","optimizer":"","assistant":"","creator":"吴丹丹","createTime":"2026-06-23 11:25","updateTime":"2026-06-23 11:25","lastFollowTime":"2026-07-29 11:29","lastFollowContent":"加微信，一直没通过","nextFollowTime":"2026-07-30 10:00","followCount":0,"daysHeld":0,"trashCount":0,"transformStatus":false,"isOverdue":false,"remark":"","customerBudget":"","customerCost":"1156100","presalesGroupName":"","prototypeLink":"","witkeyId":"","witkeyTaskNo":"","customerNote":"","initialRequirement":""}', '2026-06-23 11:25', 0) ON CONFLICT (id) DO NOTHING;
