INSERT INTO leads (id, data, updated_at, version) VALUES ('L-5828', '{"id":"L-5828","key":"L-5828","name":"软件测试","customer":"","contact":"","phone":"","wechat":"","source":"website","keyword":"","status":"未联系","clueType":"trash","level":"","customerLevel":"S","tags":["客户的业务范围是做汽车后付市场，主要对接的就是你们平时去洗车或者是去贴膜的这样的一个店面，帮他们去做陪跑。陪跑的内容的话，是短视频的拍剪，然后呢。抖音的流量投放包括流量投放完以后，抖音后台的客资转化和分配，然后再到后面儿的这个邀约进店和升单，这是我们的业务范围。那配套的软件功能要求就第一个就是。AI客服，他从后端接着客资的分发，然后第二个需求的话，就是有部分店面他在拍视频上有困难，所以说我们需要AI混剪的功能来帮他们去先去做一个基础的一个过渡。第三的话就是。因为还涉及到邀约进店以后，还涉及到客户管理，所以说我们需要能够衔接的GM系统，帮他们去把客户做一个管理。那最后就是GEO。"],"entity":"","owner":"","optimizer":"","assistant":"周欢","creator":"吴丹丹","createTime":"2026-07-01 18:39","updateTime":"2026-07-01 18:39","lastFollowTime":"2026-07-30 16:44","lastFollowContent":"做不了，不做了","nextFollowTime":"2026-07-31 10:00","followCount":0,"daysHeld":0,"trashCount":1,"transformStatus":false,"isOverdue":false,"remark":"","customerBudget":"软件测试","customerCost":"","presalesGroupName":"","prototypeLink":"","witkeyId":"","witkeyTaskNo":"","customerNote":"","initialRequirement":""}', '2026-07-01 18:39', 0) ON CONFLICT (id) DO NOTHING;
