INSERT INTO leads (id, data, updated_at, version) VALUES ('L-5847', '{"id":"L-5847","key":"L-5847","name":"开发本地生活小程序","customer":"","contact":"","phone":"","wechat":"","source":"baidu","keyword":"1157871","status":"未联系","clueType":"trash","level":"","customerLevel":"A","tags":["小程序开发项目需求说明rn项目背景rn当前本地生活服务市场存在用户找店难、商家新媒体运营成本高的痛点，供需两端信息匹配效率低。为填补区域生活服务数字化缺口，方便用户快速获取周边商家信息，同时为本地中小商家提供低成本的获客渠道，计划开发一款聚焦区域本地生活服务的微信小程序。rn核心功能需求rn用户端：支持LBS周边商家检索、商家详情展示（环境图/营业时间/联系方式）、优惠优惠券领取、到店打卡、用户评价收藏、关键词搜索筛选功能；rn商家端：支持免费入驻自主编辑店铺信息、发布优惠活动、查看店铺访问数据、在线回复用户咨询；rn平台端：支持商家资质审核、内容违规检测、数据统计后台管理功能。rn盈利模式设计rn增值服务收费：基础入驻免费，针对有推广需求的商家推出付费店铺装修模板、优先排名置顶、精准流量推送等增值服务，按月/按季度收取服务费；rn交易佣金：打通小程序线上优惠券核销、团购套餐售卖功能，每笔成交订单抽取5%-8%的交易佣金；rn品牌广告位：在小程序首页、分类页开通固定Banner广告位，面向区域连锁品牌收取阶段性广告投放费用；rn异业合作分成：联合本地生活服务平台推出联名活动，获取合作分成收益。"],"entity":"","owner":"","optimizer":"","assistant":"","creator":"吴丹丹","createTime":"2026-07-16 10:09","updateTime":"2026-07-16 10:09","lastFollowTime":"2026-07-29 17:14","lastFollowContent":"不是做开发的需求，要找代理商合作","nextFollowTime":"2026-07-30 10:00","followCount":0,"daysHeld":0,"trashCount":1,"transformStatus":false,"isOverdue":false,"remark":"","customerBudget":"","customerCost":"","presalesGroupName":"","prototypeLink":"","witkeyId":"","witkeyTaskNo":"","customerNote":"","initialRequirement":""}', '2026-07-16 10:09', 0) ON CONFLICT (id) DO NOTHING;
